{
  "technical_and_design_decisions": [
    "Use Spring XD's existing module and message bus abstraction; add new configuration properties via ModuleDeploymentProperties and bus-specific properties.",
    "For RabbitMQ retry control, implement a configurable list/set of non-retryable exception class names evaluated in the bus error handler; default includes org.springframework.amqp.support.converter.MessageConversionException (resolved by name to avoid class visibility issues), org.springframework.messaging.converter.MessageConversionException, and Kryo deserialization exceptions.",
    "Resolve the ClassNotFoundException by referencing AMQP exception classes via string names / bus classloader rather than requiring the module classpath to contain the AMQP library.",
    "Expose module id and container id through Spring Environment properties (e.g., xd.module.id, xd.container.id) and populate logging MDC at module startup.",
    "Extend Kafka bus properties with consumer (autoCommitEnabled, queueSize, maxWait, fetchSize) and producer (batchSize, batchTimeout) fields and map them to Kafka client configurations.",
    "Perform dependency upgrades (Spring Integration 4.1.5, SI Kafka 1.2.0, Spring Hadoop 2.2.0) by adjusting Maven version properties and fixing any deprecated API usage; no major architectural changes.",
    "Implement the landing page as a lightweight addition to the existing Spring XD admin UI, reusing current UI framework and routing.",
    "Consolidate RPM scripts into a single public Git repository with subdirectories for XD and XD+Ambari, preserving existing script logic."
  ],
  "assumptions": [
    "Existing Spring XD source code is available, builds locally with Maven, and the developer is familiar with the codebase.",
    "Integration test environments for RabbitMQ, Kafka, and Hadoop are available or can be sufficiently mocked; estimate covers unit and local integration testing.",
    "Effort estimates include coding, unit testing, local verification, and documentation, but exclude external review cycles, production deployment, and formal UAT.",
    "U1 landing page is a minor UI addition, not a full redesign; existing UI components are reused.",
    "For U8, RPM scripts already exist and only need relocation/consolidation, not authoring from scratch.",
    "All estimates are expressed in work-hours for a single experienced developer.",
    "Kryo deserialization problems are represented by KryoException or a clear subclass and can be added to the default non-retryable list.",
    "No significant breaking API changes exist in the specified dependency upgrades beyond typical minor-version adjustments."
  ],
  "activities": [
    {
      "activity_id": "A01",
      "activity_name": "Initial setup and impact analysis",
      "activity_description": "Check out Spring XD source, set up build environment, and analyze impact of all user stories across modules and buses.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A02",
      "activity_name": "Landing page with section links (U1)",
      "activity_description": "Implement a new landing page/view in the admin UI providing higher-order links to sources, processors, sinks, and jobs.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A03",
      "activity_name": "Configurable Rabbit retry exceptions (U2)",
      "activity_description": "Design and implement properties at bus and stream deployment level to configure which exceptions are retryable/non-retryable within RabbitMessageBus.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A04",
      "activity_name": "Fix Rabbit exception handling and Kryo retry (U2)",
      "activity_description": "Resolve ClassNotFoundException for AMQP MessageConversionException, ensure messaging MessageConversionException and Kryo deserialization exceptions stop retries.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A05",
      "activity_name": "Upgrade Spring Integration to 4.1.5 (U3)",
      "activity_description": "Bump Spring Integration dependency to 4.1.5, resolve compatibility issues, and run tests.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "A06",
      "activity_name": "Upgrade SI Kafka extension to 1.2.0 (U4)",
      "activity_description": "Bump Spring Integration Kafka extension dependency to 1.2.0, resolve compatibility issues, and run tests.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "A07",
      "activity_name": "Upgrade Spring Hadoop to 2.2.0 GA (U5)",
      "activity_description": "Bump Spring Hadoop dependency to 2.2.0 GA, adjust code for API changes, and test.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A08",
      "activity_name": "Expose module and container IDs (U6)",
      "activity_description": "Provide API/Spring Environment properties for module id and container id accessible to source/processor/sink components.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A09",
      "activity_name": "Include IDs in component logging (U6)",
      "activity_description": "Configure logging framework (MDC/pattern) to output module id and container id in component logs.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A10",
      "activity_name": "Kafka bus property overrides (U7)",
      "activity_description": "Implement support for overriding consumer (autoCommitEnabled, queueSize, maxWait, fetchSize) and producer (batchSize, batchTimeout) defaults in Kafka bus.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A11",
      "activity_name": "Consolidate RPM scripts into single repo (U8)",
      "activity_description": "Move/merge XD and XD+Ambari RPM scripts into a single public repository and verify build scripts.",
      "most_likely_effort": 14
    },
    {
      "activity_id": "A12",
      "activity_name": "Documentation and user guide updates",
      "activity_description": "Document new landing page, retry properties, module/container IDs, Kafka overrides, dependency upgrades, and RPM repo location.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A13",
      "activity_name": "Integration testing and build verification",
      "activity_description": "Execute full build, unit/integration tests for all changes, and fix defects found.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A14",
      "activity_name": "Release preparation and versioning",
      "activity_description": "Update version numbers, release notes, commit and tag the software increment.",
      "most_likely_effort": 6
    }
  ],
  "reported_total": {
    "most_likely_effort": 192
  }
}

